pub struct Label {
    text: String,
}

impl Label {
    pub fn new(text: String) -> Self {
        Label { text }
    }
}

pub fn render(labels: &[Label], prefix: String) -> String {
    let mut out = String::new();
    for label in labels {
        out.push_str(&prefix.clone());
        out.push_str(&label.text.clone());
        out.push('\n');
    }
    out
}

