pub fn new(text: &str) -> Self {
    Label { text: text.to_string() }
}

pub fn render(labels: &[Label], prefix: &str) -> String {
    let mut out = String::new();
    for label in labels {
        out.push_str(prefix);
        out.push_str(&label.text);
        out.push('\n');
    }
    out
}

pub fn new(text: impl Into<String>) -> Self {
    Label { text: text.into() }
}
